examples.template:
MonarchSectionCard(
    {{title}},
    description: {{description}},
    systemImage: "clock"
) {
    VStack(alignment: .leading, spacing: 4) {
        Text("• " + {{tasks.0}}).monarchTextStyle(.body)
        Text("• " + {{tasks.1}}).monarchTextStyle(.body)
        Text("• " + {{tasks.2}}).monarchTextStyle(.body)
    }
} actions: {
    MonarchButton({{addLabel}}, systemImage: "plus", size: .sm) {}
    MonarchButton({{linkLabel}}, trailingSystemImage: "chevron.right", variant: .ghost, size: .sm) {}
} footer: {
    Text({{footer}}).monarchTextStyle(.caption)
}
.monarchMetaBadge({{meta}})

examples.code:
